window.__ModuleLoader__.load({
  id: "dsh-brand-logo",
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    // Generated by tools/set-logo.mjs and tools/set-text.mjs — edit the source
    // image or the type settings, not this block.
    // Source: typeset: DEEPSEEK + HARNESS
    const BRAND = {
      "mode": "text",
      "parts": [
        {
          "text": "DEEPSEEK",
          "weight": 500,
          "opacity": 1
        },
        {
          "text": "HARNESS",
          "weight": 400,
          "opacity": 0.6
        }
      ],
      "font": "var(--dsw-font-family-brand)",
      "size": 13,
      "tracking": ".12em",
      "gap": 6,
      "transform": "uppercase"
    };

    function Logo(props) {
      return h('img', {
        src: BRAND.url,
        alt: '',
        'aria-hidden': true,
        draggable: false,
        style: Object.assign({
          display: 'block',
          objectFit: 'contain',
          objectPosition: 'left center',
        }, props.style),
      });
    }

    /**
     * `sidebar.brand.mark` — the square mark left of the wordmark (expanded)
     * and alone in the collapsed rail. Only a square image takes this seat; a
     * wordmark or a typeset name leaves it to the shipped mark.
     */
    function BrandMark(owner) {
      if (BRAND.mode !== 'icon') return null;
      const size = owner && typeof owner.size === 'number' ? owner.size : 24;
      return h(Logo, { style: { width: size, height: size, maxWidth: '100%' } });
    }

    /**
     * `sidebar.brand.name` — the wordmark right of the mark: either the
     * configured image, or the typeset lockup (name in the app's brand face:
     * heavier first word, lighter second word, wide tracking).
     */
    function BrandName() {
      if (BRAND.mode === 'wide') {
        return h(Logo, { style: { height: BRAND.height, width: 'auto', maxWidth: '100%' } });
      }
      if (BRAND.mode !== 'text') return null;
      return h('span', {
        'aria-label': BRAND.parts.map((part) => part.text).join(' '),
        style: {
          display: 'inline-flex',
          alignItems: 'baseline',
          gap: BRAND.gap + 'px',
          color: 'inherit',
          fontFamily: BRAND.font,
          fontSize: BRAND.size + 'px',
          fontWeight: 400,
          letterSpacing: BRAND.tracking,
          lineHeight: 1,
          textTransform: BRAND.transform || 'uppercase',
          whiteSpace: 'nowrap',
        },
      }, BRAND.parts.map((part, index) => h('span', {
        key: index,
        style: { fontWeight: part.weight, opacity: part.opacity === undefined ? 1 : part.opacity },
      }, part.text)));
    }

    return {
      inject: ['slots'],
      apply(ctx) {
        // Both seats are single slots and the official brand already holds them
        // at the default rank 0 (a second registration at 0 throws), so a lower
        // rank shadows it; the lowest rank renders and the official plugin can
        // stay enabled. -10 mirrors the rank liveshare uses for the same seats.
        // A mode that does not need a seat stays out of it entirely, so the
        // shipped whale or wordmark keeps rendering there.
        if (BRAND.mode === 'icon') {
          ctx.slots.inject('sidebar.brand.mark', () => ctx.slots.register({
            name: 'sidebar.brand.mark',
            id: 'brand-logo-mark',
            priority: -10,
          }, BrandMark));
        } else {
          ctx.slots.inject('sidebar.brand.name', () => ctx.slots.register({
            name: 'sidebar.brand.name',
            id: 'brand-logo-name',
            priority: -10,
          }, BrandName));
        }
      },
    };
  },
});
